package org.local.donusturucu.qa;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.media.MediaMetadataRetriever;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.security.*;import org.json.*;
public class FolderMerge extends FileList {
 File asset(String name,File root)throws Exception{File file=new File(root,name);InputStream in=getContext().getAssets().open(name);OutputStream out=new FileOutputStream(file);try{byte[]buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}finally{in.close();out.close();}return file;}
 List<String> pixels(File file)throws Exception{List<String>hashes=new ArrayList<String>();ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer pdf=new PdfRenderer(fd);try{for(int i=0;i<pdf.getPageCount();i++){PdfRenderer.Page page=pdf.openPage(i);Bitmap bitmap=Bitmap.createBitmap(page.getWidth(),page.getHeight(),Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);int[]pixels=new int[bitmap.getWidth()*bitmap.getHeight()];bitmap.getPixels(pixels,0,bitmap.getWidth(),0,0,bitmap.getWidth(),bitmap.getHeight());MessageDigest digest=MessageDigest.getInstance("SHA-256");for(int pixel:pixels)digest.update(new byte[]{(byte)(pixel>>24),(byte)(pixel>>16),(byte)(pixel>>8),(byte)pixel});hashes.add(Arrays.toString(digest.digest()));page.close();bitmap.recycle();}}finally{pdf.close();fd.close();}return hashes;}
 byte[] pcm(Method execute,File source,File out,double start)throws Exception{execute.invoke(activity,new ArrayList<String>(Arrays.asList("ffmpeg","-v","error","-protocol_whitelist","file,pipe","-ss",Double.toString(start),"-i",source.toString(),"-t","0.3","-vn","-ar","16000","-ac","1","-f","s16le","-y",out.toString())));InputStream in=new FileInputStream(out);ByteArrayOutputStream b=new ByteArrayOutputStream();try{byte[]buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)b.write(buffer,0,n);}finally{in.close();}return b.toByteArray();}
 double[] samples(byte[]bytes){double[]out=new double[bytes.length/2];for(int i=0;i<out.length;i++)out[i]=(short)((bytes[2*i]&255)|(bytes[2*i+1]<<8))/32768d;return out;}
 double rms(double[]samples){double sum=0;for(double value:samples)sum+=value*value;return Math.sqrt(sum/samples.length);}
 double correlation(double[]a,double[]b){double best=-1;int n=Math.min(a.length,b.length);for(int shift=-16;shift<=16;shift++){double aa=0,bb=0,ab=0;for(int i=16;i<n-16;i++){double x=a[i],y=b[i+shift];aa+=x*x;bb+=y*y;ab+=x*y;}if(aa>0&&bb>0)best=Math.max(best,ab/Math.sqrt(aa*bb));}return best;}
 public void onStart(){Bundle result=new Bundle();try{Intent intent=new Intent();intent.setClassName("org.local.donusturucu","org.local.donusturucu.MainActivity");intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=startActivitySync(intent);long until=System.currentTimeMillis()+60000;while(!(Boolean)get("ready")&&System.currentTimeMillis()<until)Thread.sleep(200);require((Boolean)get("ready"));File root=new File(getTargetContext().getExternalFilesDir(null),"folder-merge-test");root.mkdirs();ClassLoader loader=activity.getClassLoader();Class<?>engine=Class.forName("org.local.donusturucu.MediaEngine",true,loader),host=Class.forName("org.local.donusturucu.MediaEngine$Host",true,loader),docs=Class.forName("org.local.donusturucu.DocumentEngine",true,loader),docHost=Class.forName("org.local.donusturucu.RichDocument$Host",true,loader);final Method execute=activity.getClass().getDeclaredMethod("execute",List.class),probe=activity.getClass().getDeclaredMethod("probe",File.class);execute.setAccessible(true);probe.setAccessible(true);Object callback=Proxy.newProxyInstance(loader,new Class<?>[]{host},new InvocationHandler(){public Object invoke(Object p,Method m,Object[]args)throws Throwable{if(m.getName().equals("run")){execute.invoke(activity,args[0]);}return null;}}),docCallback=Proxy.newProxyInstance(loader,new Class<?>[]{docHost},new InvocationHandler(){public Object invoke(Object p,Method m,Object[]args){return null;}});JSONArray rows=new JSONArray();
 List<File>pdfs=Arrays.asList(asset("pages.pdf",root),asset("blank-middle.pdf",root),asset("blank-edges.pdf",root));List<String>expected=new ArrayList<String>();for(File file:pdfs)expected.addAll(pixels(file));List<File>videos=new ArrayList<File>(),audios=Arrays.asList(asset("short-en.wav",root),asset("short-tr.wav",root),asset("long-en.wav",root));for(int n=0;n<3;n++)videos.add(asset("folder-video-"+n+".mp4",root));
 for(int repeat=1;repeat<=3;repeat++)for(String kind:new String[]{"pdf","audio","video"}){JSONObject row=new JSONObject();row.put("repeat",repeat);row.put("kind",kind);File work=new File(root,kind+repeat);work.mkdirs();List<File>sources=kind.equals("pdf")?pdfs:kind.equals("audio")?audios:videos;List<String>before=new ArrayList<String>();for(File file:sources)before.add(hash(file));File output;if(kind.equals("pdf")){output=(File)docs.getMethod("mergeMany",List.class,File.class,docHost).invoke(null,sources,work,docCallback);require(pixels(output).equals(expected));row.put("rendered_pages",expected.size());row.put("pixel_content_preserved",true);}else{List<Object>infos=new ArrayList<Object>();double duration=0;for(File file:sources){Object info=probe.invoke(activity,file);infos.add(info);duration+=info.getClass().getField("duration").getDouble(info);}Object instance=engine.getConstructor(host,File.class).newInstance(callback,work);List<File>products=(List<File>)engine.getMethod("mergeMany",List.class,List.class).invoke(instance,sources,infos);output=products.get(0);Object info=probe.invoke(activity,output);double actual=info.getClass().getField("duration").getDouble(info);require(Math.abs(actual-duration)<.25);row.put("duration",actual);row.put("expected_duration",duration);if(kind.equals("audio")){double position=0;for(int i=0;i<sources.size();i++){double length=infos.get(i).getClass().getField("duration").getDouble(infos.get(i));double[]reference=samples(pcm(execute,sources.get(i),new File(work,"ref"+i+".pcm"),length/4)),actualSamples=samples(pcm(execute,output,new File(work,"out"+i+".pcm"),position+length/4));require(rms(actualSamples)>.002&&correlation(reference,actualSamples)>.95);position+=length;}row.put("three_audio_parts_correlate",true);}if(kind.equals("video")){MediaMetadataRetriever retriever=new MediaMetadataRetriever();retriever.setDataSource(output.getAbsolutePath());double position=0;for(int i=0;i<3;i++){double length=infos.get(i).getClass().getField("duration").getDouble(infos.get(i));Bitmap frame=retriever.getFrameAtTime((long)((position+length/2)*1000000),MediaMetadataRetriever.OPTION_CLOSEST);require(frame!=null);int color=frame.getPixel(frame.getWidth()/2,frame.getHeight()/2);if(i==0)require(Color.red(color)>180&&Color.blue(color)<50);if(i==1)require(Color.blue(color)>180&&Color.red(color)<50);if(i==2)require(Color.green(color)>80&&Color.red(color)<50);frame.recycle();position+=length;}retriever.release();row.put("three_video_parts_present",true);}}
 for(int i=0;i<sources.size();i++)require(before.get(i).equals(hash(sources.get(i))));row.put("source_count",3);row.put("originals_unchanged",true);row.put("pass",true);rows.put(row);JSONObject report=new JSONObject();report.put("cases",rows.length());report.put("failures",0);report.put("rows",rows);SubtitleRoundtrip.write(new File(root,"report.json"),report.toString(2));}
 finish(0,result);
 }catch(Throwable error){result.putString("error",error.toString());if(error instanceof InvocationTargetException)result.putString("cause",((InvocationTargetException)error).getCause().toString());finish(1,result);}}
}
